findings=[
 {'id':'CLV01','issue':'Fractional platelet gap and false source certainty','before':'Platelet80–99 held as if stated by source;99.5 was missed.','after':'80 to<100 consistently triggers source-gap review; a documented prior hold separately requires recovery to≥100.','source':'NCCPp3Table1'},
 {'id':'CLV02','issue':'Current counts did not preserve delay/nadir/dose history','before':'An isolated low count described an80% restart without requiring prior-dose recovery reconciliation.','after':'Both recovery counts, prior delay, number of delays, dose changes and nadir are distinguished.80% original becomes new full dose; no repeated percentage multiplication or re-escalation.','source':'NCCPp3Table1;lomustineSmPC4.2'},
 {'id':'CLV03','issue':'Separate renal bands could disagree and conceal decimals','before':'Two manually selected component renal bands; no decimal gap or missing-dialysis safeguards.','after':'One exact CrCl plus explicit dialysis;39.999/40,49/49.001/50,59/59.001/60 and30/50 boundaries tested. Not-recommended wording remains distinct from formal severe-renal exclusion.','source':'NCCPp3Table2'},
 {'id':'CLV04','issue':'Severe hepatic limitation missing','before':'Only vincristine bilirubin captured.','after':'Lomustine severe hepatic not-recommended pathway, clinician-assigned severity, mild/moderate table context and unresolved vincristine bilirubin fraction.','source':'NCCPp3Table2'},
 {'id':'CLV05','issue':'Neurotoxicity provenance and history incomplete','before':'Source labelled CTCAE5 despite no edition; no prior Grade2 recovery or Grade3/4 omission history.','after':'Named source grading, explicit recovery and previous reduction/omission. Grade2 withhold, Grade3/4 omit. Product cisplatin neurological review stays component-specific.','source':'NCCPp4Table3;cisplatinSmPC4.4'},
 {'id':'CLV06','issue':'Eligibility and schedule not structured','before':'No exact post-RT timing, cycle limit or three-component dose viewer.','after':'Adult medulloblastoma/PNET classification, age>40 exclusion, first cycle4–6weeks after craniospinalRT; eight42-day cycles with Day1CLV and Day8/15vincristine,2mg cap retained.','source':'NCCPpp1–2'},
 {'id':'CLV07','issue':'Delayed cumulative lomustine safety missing','before':'No six-week redose guard, weekly-count plan, lifetime exposure, prior-nadir or pulmonary risk threshold.','after':'Single-dose supply check,≥42-day interval, weeklycounts≥6weeks, lifetime1000mg/m² maximum including proposed dose, FVC/DLCO<70% risk review and product-specific contraindications.','source':'LomustineSmPC4.2–4.5'},
 {'id':'CLV08','issue':'Supportive care and administration gaps','before':'Hydration only.','after':'Day1 vsDay8/15 emetic burden, aprepitant/azole review, local antifungal plan, constipation prevention/urgent bowel symptoms, IV-only minibag safeguards, hearing and renal/electrolyte concerns.','source':'NCCPpp1,2,4;cisplatinSmPC4.4'},
 {'id':'CLV09','issue':'Current product conflict not represented','before':'No product reconciliation.','after':'NCCP1h cisplatin/localhydration vs currentAccord6–8h and different hydration/diuresis; reduced renal bands vs product pre-existing renal contraindication; component-specific repeat counts and creatinine equality ambiguity explicitly blocked from automatic dose.','source':'NCCPpp1,3;cisplatinSmPC4.2–4.4'},
 {'id':'CLV10','issue':'Supplementary-source uncertainty needed retention','before':'No visible conflicts for WBC vsANC or product nadir overlap.','after':'Manufacturer WBC/prior-dose table differs from NCCP ANC/original-dose table; platelet nadir24–<25 overlap and unverified current vincristine SmPC retained as limitations.','source':'NCCPpp3–4;lomustineSmPC4.2;retrieval404'},
]
